<script setup>
import {computed,onMounted,ref} from 'vue';
import Icon from '../Icon.vue';
import {api,money,localDate} from '../../lib';
const report=ref(null),loading=ref(true),error=ref(''),period=ref('week'),from=ref(''),to=ref(localDate());
function preset(){const now=new Date(`${localDate()}T12:00:00+07:00`);to.value=localDate(now);if(period.value==='week')now.setUTCDate(now.getUTCDate()-6);else now.setUTCDate(1);from.value=localDate(now);load();}
async function load(){loading.value=true;error.value='';try{report.value=await api(`/admin/reports?from=${from.value}&to=${to.value}`);}catch(e){error.value=e.message;}finally{loading.value=false;}}
const maxDaily=computed(()=>Math.max(...(report.value?.daily.map(x=>x.revenue)||[]),1));
const maxHourly=computed(()=>Math.max(...(report.value?.hours.map(x=>x.count)||[]),1));
onMounted(preset);
</script>
<template><form class="admin-toolbar report-filter" @submit.prevent="load"><div class="filter-tabs"><button type="button" :class="{active:period==='week'}" @click="period='week';preset()">7 hari terakhir</button><button type="button" :class="{active:period==='month'}" @click="period='month';preset()">Bulan ini</button></div><div class="toolbar-actions"><label>Dari<input v-model="from" type="date" required/></label><label>Sampai<input v-model="to" type="date" required :min="from"/></label><button class="button secondary" :disabled="loading"><Icon name="RefreshCw" :size="16"/>Tampilkan</button></div></form><p v-if="error" class="alert error" role="alert">{{error}}</p><div v-if="loading" class="skeleton table-skeleton"></div><template v-else-if="report"><div class="metric-grid report-metrics"><div class="metric"><span>Omzet penjualan</span><strong>{{money(report.revenue)}}</strong></div><div class="metric"><span>Pesanan selesai & lunas</span><strong>{{report.order_count}}<small>pesanan</small></strong></div><div class="metric"><span>Rata-rata per pesanan</span><strong>{{money(report.average)}}</strong></div></div><div v-if="!report.order_count" class="panel empty-state"><Icon name="BarChart3" :size="38"/><h2>Belum ada penjualan pada periode ini</h2><p>Pesanan dihitung setelah berstatus Selesai dan Lunas. Coba rentang tanggal lain.</p></div><template v-else><div class="report-charts"><section class="panel"><h2>Omzet per hari</h2><p class="muted small">Berdasarkan tanggal pesanan diselesaikan (WIB).</p><div class="horizontal-chart"><div v-for="day in report.daily" :key="day.date" class="chart-row"><span>{{day.date.slice(5).split('-').reverse().join('/')}}</span><div class="chart-track"><i :style="{width:(day.revenue/maxDaily*100)+'%'}"></i></div><strong>{{money(day.revenue)}}</strong></div></div></section><section class="panel"><h2>Jam ramai</h2><p class="muted small">Jam masuk pesanan yang telah selesai dan lunas (WIB).</p><div class="hour-chart"><div v-for="item in report.hours" :key="item.hour"><span>{{item.count}}</span><i :style="{height:(item.count/maxHourly*130)+'px'}" :title="`${item.hour}:00 — ${item.count} pesanan`"></i><small>{{String(item.hour).padStart(2,'0')}}</small></div></div></section></div><section class="panel"><h2>Menu terlaris</h2><div class="table-wrap borderless"><table><thead><tr><th>Menu</th><th>Terjual</th><th>Penjualan</th></tr></thead><tbody><tr v-for="(item,i) in report.popular" :key="i"><td><span class="rank">{{i+1}}</span><strong>{{item.name}}</strong></td><td>{{item.quantity}} porsi</td><td>{{money(item.revenue)}}</td></tr></tbody></table></div></section></template><p class="table-caption">Data laporan hanya berasal dari pesanan Selesai dan Lunas. Seluruh tanggal menggunakan WIB.</p></template></template>
